/**
 * Segmented. Molded uppercase segments in a recessed well; the active segment
 * lights as the primary cap. Composes var(--echo-*).
 */
.echo-segmented {
  /* One size scale (sm/md/lg): the well's outer height is the control height. */
  --ctl-h: var(--echo-control-default);
  --seg-well: var(--echo-space-3);
  --seg-px: var(--echo-space-8);
  --seg-font: var(--echo-text-xs);
  /* The light is positioned against the well and scrolls with the options. */
  position: relative;
  display: inline-flex;
  /*
   * Three options ("Focus / Break / Rest") in a 200px settings column
   * measured 253, so the last one was clipped by the panel edge. A user on a
   * phone could not see or reach one of three choices.
   *
   * The first fix was `flex-wrap: wrap`, which kept every option on screen
   * but broke the control: the well grew a second row with REST alone under
   * FOCUS, which no longer reads as ONE segmented selector. A segmented control
   * is a single row by definition. So the row never wraps; when it is out of
   * room it scrolls, the way a phone's scrolling segmented bar does. Every
   * option is still reachable — by swipe, and by the arrow keys, which move
   * focus and so scroll the focused segment into view natively.
   */
  flex-wrap: nowrap;
  /* As a flex item it would floor at its content width and push its row open;
     with min-width: 0 it shrinks and scrolls inside itself instead. */
  min-width: 0;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
  gap: var(--echo-space-2);
  max-width: 100%;
  box-sizing: border-box;
  height: var(--ctl-h);
  padding: var(--seg-well);
  /* At roundness 1 (--echo-cap-round) the well and its segments are pills. */
  --seg-well-radius: max(var(--echo-radius-xl), calc(var(--echo-cap-round, 0) * 999px));
  --seg-radius: max(var(--echo-radius-md), calc(var(--echo-cap-round, 0) * 999px));
  border-radius: var(--seg-well-radius);
  /* Deep recessed well — same near-black recipe as the Field. */
  background: var(--echo-drawn-hollow, linear-gradient(
    160deg,
    color-mix(in oklab, var(--echo-well) 72%, var(--echo-shade-ink, black)),
    color-mix(in oklab, var(--echo-lcd) 88%, var(--echo-shade-ink, black))
  ));
  box-shadow: var(
    --echo-shadow-well,
    inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent)
  );
}
.echo-segmented[data-size="sm"] {
  --ctl-h: var(--echo-control-compact);
  --seg-well: var(--echo-space-1);
  --seg-px: var(--echo-space-6);
  --seg-font: var(--echo-text-2xs);
}
.echo-segmented[data-size="lg"] {
  --ctl-h: var(--echo-control-large);
  --seg-well: var(--echo-space-3);
  --seg-px: var(--echo-space-9);
  --seg-font: var(--echo-text-sm);
}

.echo-segmented::-webkit-scrollbar {
  display: none;
}

.echo-segmented__option {
  /*
   * Long content. A segment keeps its label on one line and the row
   * scrolls — breaking a label mid-word inside a cap reads as a rendering
   * fault, and a segment is a short word by contract (see meta.ts).
   */
  flex: 0 0 auto;
  white-space: nowrap;
  position: relative;
  /* The lit cap can be dragged across the labels; dragging must not select them. */
  user-select: none;
  -webkit-user-select: none;
  border: 0;
  display: inline-flex;
  align-items: center;
  box-sizing: border-box;
  height: 100%;
  padding: 0 var(--seg-px);
  border-radius: var(--seg-radius);
  cursor: pointer;
  background: transparent;
  /* The theme's dim text, held to AA on the well; the text at half strength read at APCA Lc 36. */
  color: var(--echo-text-dim);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--seg-font);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-wider, 0.12em);
  text-transform: uppercase;
  transition: color var(--echo-duration-swap) ease;
}

/* The active segment lights as the primary cap. */
/* An option with content stacks it, centred, and sizes to it. */
.echo-segmented__option[data-content] {
  flex-direction: column;
  justify-content: center;
  gap: var(--echo-space-1);
  line-height: var(--echo-leading-none, 1);
}

.echo-segmented__option[aria-checked="true"] {
  color: var(--echo-primary-cap-ink, var(--echo-text));
  background: linear-gradient(
    180deg,
    var(--echo-primary-cap-top) 0%,
    var(--echo-primary-cap-mid) 45%,
    var(--echo-primary-cap-base) 100%
  );
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.4 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent),
    0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.4 * var(--echo-shade, 1) * 100%), transparent);
}

/*
 * The moving light. segmented.tsx places it under the selected option and
 * sets data-light on the well; from then on it is what draws the lit cap, and
 * the options only carry their labels. Its box is written inline from the
 * option's measured offsets, which are physical in either direction.
 */
.echo-segmented__light {
  position: absolute;
  z-index: var(--echo-z-base, 0);
  visibility: hidden;
  pointer-events: none;
  /* A drop shadow rather than a box shadow: it follows whatever outline
     the shape inside takes. Longer and softer as the cap lifts. */
  filter: drop-shadow(
    0 calc(2px + 4px * var(--lift, 0)) calc(2.5px + 4px * var(--lift, 0))
      color-mix(in oklab, var(--echo-cast-ink, black) calc(0.4 * var(--echo-shade, 1) * 100%), transparent)
  );
  will-change: transform, left, width;
}
/* The lit material itself, clipped to the cap's current outline. */
.echo-segmented__shape {
  border-radius: var(--seg-radius);
  background: linear-gradient(
    180deg,
    var(--echo-primary-cap-top) 0%,
    var(--echo-primary-cap-mid) 45%,
    var(--echo-primary-cap-base) 100%
  );
  /* Drawn, the chosen segment is outlined in the ink inside the well's own line. */
  box-shadow:
    var(--echo-shadow-edge, inset 0 1px 0 rgb(255 255 255 / calc(0.4 * var(--echo-gloss, 1)))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}
.echo-segmented__shape {
  position: absolute;
  inset: 0;
}
/* In flight, the key light's highlight rolls across the drop (--sheen is
   where it falls, --roll how strongly, both from speed). */
.echo-segmented__shape::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    ellipse at var(--sheen, 50%) 0%,
    rgb(255 255 255 / calc(0.35 * var(--echo-gloss, 1))),
    transparent 65%
  );
  opacity: var(--roll, 0);
}

.echo-segmented__option {
  z-index: var(--echo-z-raised, 1);
}
.echo-segmented[data-light] .echo-segmented__option[aria-checked="true"]:not(:focus-visible) {
  background: transparent;
  box-shadow: none;
}
/* Each label is lit by how much of the cap covers it (--on, 0–1), so the
   light brightens a label as it slides under, not when the value flips: from
   the dim label on the well to the lit cap's own label (the text on a dark
   device, where this is the text coming up to full strength). */
.echo-segmented[data-light] .echo-segmented__option {
  color: color-mix(
    in oklab,
    var(--echo-primary-cap-ink, var(--echo-text)) calc(100% * var(--on, 0)),
    var(--echo-text-dim)
  );
  transition: background var(--echo-duration-tick) var(--echo-ease-tick);
}
/* A faint pill under an option the pointer is over: it could be chosen. */
@media (hover: hover) {
  .echo-segmented__option:not([aria-checked="true"]):not(:disabled):not([data-disabled]):hover {
    background: color-mix(in oklab, var(--echo-text) 6%, transparent);
  }
}

.echo-segmented__option:focus-visible {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: -2px;
  box-shadow: 0 0 0 2px var(--echo-accent-ink, var(--echo-accent-glow));
}

.echo-segmented__option:disabled,
.echo-segmented__option[data-disabled] {
  cursor: default;
  opacity: 0.5;
}

@media (prefers-reduced-motion: reduce) {
  .echo-segmented__option {
    transition: none;
  }
}

/*
 * Coarse-pointer targets.
 *
 * These already clear WCAG 2.2 2.5.8's 24px. This is the 44px both
 * platform guidelines use — a fingertip rather than conformance. Gated on
 * `@media (pointer: coarse)`, so the desktop rendering does not move.
 *
 * Where a control's visual size is the design (a 24px checkbox, a 10px pip),
 * the target is grown with the same transparent pseudo-element as the 24px minimum,
 * not by growing the control.
 */
/* The hit area is the segment's full height, well included, so md is a
   44px target inside a 44px well. */
.echo-segmented__option::after {
  content: "";
  position: absolute;
  inset-block: calc(-1 * var(--seg-well));
  inset-inline: 0;
}

@media (pointer: coarse) {
  /* md and lg are 44px and up; sm grows to it on a touch screen. */
  .echo-segmented[data-size="sm"] {
    --ctl-h: 44px;
  }
}

/*
 * Forced colors (Windows High Contrast) drops gradients and shadows, which is
 * everything that draws this control's state. System colors draw it instead;
 * nothing here sets forced-color-adjust: none, so focus outlines still show.
 */
@media (forced-colors: active) {
  .echo-segmented__light {
    display: none;
  }
  .echo-segmented {
    border: var(--echo-border-hairline, 1px) solid ButtonText;
  }
  /* Selected reads like a selected tab: Highlight text and edge on the canvas.
     Not text on a Highlight fill: forced colors paints a Canvas backplate
     behind text, which hid HighlightText completely. The Canvas-colored
     border on every option keeps the selected one from shifting its row. */
  .echo-segmented__option {
    border: var(--echo-border-thick, 2px) solid Canvas;
  }
  .echo-segmented__option[aria-checked="true"] {
    color: Highlight;
    border-color: Highlight;
  }
}

"use client";

/**
 * Segmented. Molded segments in a recessed well; the active segment lights as
 * the primary cap. A value
 * selector — a radiogroup with roving focus + arrow-key selection and a select
 * sound on change — distinct from Tabs, which switches content panels.
 *
 * The API mirrors the reference: `options` labels + a numeric selected index.
 *
 * The lit cap is a part you move, not a highlight that jumps. It notices the
 * pointer: hovering the control raises it a little and it leans your way.
 * Pressing an option pops it up out of the well, leaning toward what you
 * pressed; it glides over while lifted, on a real spring, flowing into a
 * drop as it goes — the front swelling round, the tail thinning behind,
 * drawn out by speed — and drops back into the well, a cap again, when it
 * arrives. Choosing again mid-flight bends its path
 * rather than restarting it, and the labels light as it passes under them.
 * Grab the lit cap and it follows the finger, rubber-banding at the ends; let
 * go and it lands on the nearest option, carrying the throw. Before
 * JavaScript (and in forced colors) each option lights itself, as it always
 * did.
 */
import {
  forwardRef,
  useCallback,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type MutableRefObject,
  type PointerEvent,
  type ReactNode,
} from "react";
import gsap from "gsap";
import type { EchoInterop } from "echo-ui-core/types";
import { RadioGroup as BaseRadioGroup } from "@base-ui/react/radio-group";
import { Radio as BaseRadio } from "@base-ui/react/radio";
import { useSoundOptional } from "echo-ui-core/sound";
import { springs } from "echo-ui-core/motion";
import {
  createLiquid,
  rubberband,
  timing,
  useReducedMotionRef,
  type Liquid,
} from "echo-ui-core/tactile";
import { useControlSize, type ControlSize } from "../size";
import "./segmented.css";

/**
 * A segment: its label, or `{ label, disabled }` to switch one off. Give it
 * `content` and that's what the segment shows (a day and its date, a glyph
 * and a pip), while `label` stays its accessible name.
 */
export type SegmentedOption = string | { label: string; content?: ReactNode; disabled?: boolean };

interface SegmentedOwnProps extends EchoInterop {
  options: SegmentedOption[];
  /** Selected index (controlled). */
  value?: number;
  /** Selected index for the uncontrolled case. Default 0. */
  defaultValue?: number;
  onValueChange?: (index: number) => void;
  /**
   * Height on the control scale: `sm` 32px, `md` 44px (default), `lg` 60px,
   * the same as a Field or HardwareButton of that size. Defaults to the
   * nearest SizeProvider's size.
   */
  size?: ControlSize;
}

/**
 * A control has to have a name: `aria-label`, or
 * `aria-labelledby` pointing at visible text. Leaving both out is a type
 * error, so it gets decided rather than forgotten.
 */
type AccessibleName =
  | { "aria-label": string; "aria-labelledby"?: string }
  | { "aria-labelledby": string; "aria-label"?: string };

export type SegmentedProps = SegmentedOwnProps & AccessibleName;

/*
 * On Base UI's RadioGroup. The hand-rolled
 * version hard-coded arrow directions (wrong in right-to-left), had no way to
 * disable one segment, and gave no segment a tab stop when `value` was out of
 * range, so the control couldn't be reached by keyboard. Base UI handles all
 * three: arrows follow DirectionProvider, disabled segments are skipped, and
 * with nothing selected the first enabled segment takes the tab stop.
 */
/** `forwardRef`, not a `ref` prop — see the note on `Field`. */
export const Segmented = forwardRef<HTMLDivElement, SegmentedProps>(function Segmented(
  {
    options,
    value,
    defaultValue = 0,
    onValueChange,
    size: ownSize,
    disabled,
    onKeyDown: onKeyDownProp,
    "aria-label": ariaLabel,
    "aria-labelledby": ariaLabelledby,
    ...interop
  },
  ref,
) {
  const sound = useSoundOptional();
  const size = useControlSize(ownSize);
  const isControlled = value !== undefined;
  const [internal, setInternal] = useState(defaultValue);
  const selected = isControlled ? value : internal;
  const reduced = useReducedMotionRef();
  const root = useRef<HTMLDivElement | null>(null);
  const light = useRef<HTMLSpanElement | null>(null);
  const shape = useRef<HTMLSpanElement | null>(null);
  // The lit cap: one part on a spring (echo-ui-core's liquid engine).
  const liquid = useRef<Liquid | null>(null);
  const placed = useRef(false);
  const grab = useRef<{ offset: number; startX: number; moved: boolean } | null>(null);
  // What the cap is doing, which sets how high it is lifted.
  const hovered = useRef(false);
  const pressing = useRef(false);
  const restRadius = useRef(8);
  // A glide is queued for the beat after the pop; it counts as travelling.
  const queued = useRef(false);

  const setRoot = useCallback(
    (node: HTMLDivElement | null) => {
      root.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as MutableRefObject<HTMLDivElement | null>).current = node;
    },
    [ref],
  );

  /** Every option's box, in the well's own coordinates (they scroll with it). */
  const segments = useCallback(() => {
    const r = root.current;
    if (!r) return [];
    return [...r.querySelectorAll<HTMLElement>('[role="radio"]')].map((el) => ({
      el,
      index: Number(el.dataset.index),
      left: el.offsetLeft,
      width: el.offsetWidth,
      centre: el.offsetLeft + el.offsetWidth / 2,
      top: el.offsetTop,
      height: el.offsetHeight,
      disabled: el.hasAttribute("data-disabled"),
    }));
  }, []);

  /** How high the cap sits: out of the well while pressed, grabbed or
      travelling; a little raised while the pointer is over the control. */
  const lift = useCallback(
    (name: "lift" | "rebound" = "lift", out?: boolean) => {
      const l = light.current;
      if (!l) return;
      const up =
        out ?? Boolean(grab.current || pressing.current || queued.current || liquid.current?.heading != null);
      const level = up ? 1 : hovered.current ? 0.35 : 0;
      if (reduced.current) {
        gsap.set(l, { "--lift": level });
        return;
      }
      gsap.to(l, { ...timing(name), overwrite: "auto", "--lift": level, onUpdate: () => liquid.current?.redraw() });
    },
    [reduced],
  );

  const ensureLiquid = useCallback(() => {
    const l = light.current;
    const sh = shape.current;
    if (liquid.current || !l || !sh) return liquid.current;
    liquid.current = createLiquid({
      el: l,
      shape: sh,
      restRadius: () => restRadius.current,
      // Every frame: the lift, and each label lit by how much of the cap
      // covers it — so a label brightens as the light slides under it.
      onDraw: ({ start, size }) => {
        // Under reduced motion the lift is only light (--lift, its shadow).
        const up = reduced.current ? 0 : Number(gsap.getProperty(l, "--lift")) || 0;
        gsap.set(l, { y: -1.5 * up, scale: 1 + 0.07 * up });
        for (const seg of segments()) {
          const covered = Math.max(0, Math.min(start + size, seg.left + seg.width) - Math.max(start, seg.left));
          seg.el.style.setProperty("--on", (seg.width ? covered / seg.width : 0).toFixed(3));
        }
      },
      // Arrived: set it back down into the well.
      onArrive: () => lift("rebound"),
    });
    return liquid.current;
  }, [lift, reduced, segments]);

  /* Put the cap under the selected option: instantly the first time and on
     resize, on a spring when the selection changes. */
  const place = useCallback(
    (animate: boolean, velocity?: number) => {
      const r = root.current;
      const l = light.current;
      const cap = ensureLiquid();
      if (!r || !l || !cap) return;
      const target = segments().find((s) => s.el.getAttribute("aria-checked") === "true");
      if (!target) {
        gsap.set(l, { autoAlpha: 0 });
        return;
      }
      gsap.set(l, { top: target.top, height: target.height, autoAlpha: 1 });
      restRadius.current = parseFloat(getComputedStyle(target.el).borderTopLeftRadius) || 8;
      const box = { start: target.left, size: target.width };
      if (!animate || !placed.current || reduced.current) {
        cap.place(box, "instant");
        placed.current = true;
        r.setAttribute("data-light", "");
        return;
      }
      // Out of the well first, then over: the glide starts a beat after the
      // pop, so the cap is seen to lift before it moves.
      const already = cap.heading !== null || pressing.current || grab.current;
      queued.current = true;
      lift("lift", true);
      gsap.delayedCall(already ? 0 : 0.07, () => {
        queued.current = false;
        cap.place(box, springs.snappy, velocity);
      });
    },
    [ensureLiquid, lift, reduced, segments],
  );

  useLayoutEffect(() => {
    if (!grab.current) place(true);
  }, [selected, place]);

  useLayoutEffect(() => {
    const r = root.current;
    if (!r) return;
    const resized = new ResizeObserver(() => place(false));
    resized.observe(r);
    const l = light.current;
    return () => {
      resized.disconnect();
      liquid.current?.destroy();
      liquid.current = null;
      placed.current = false;
      if (l) gsap.killTweensOf(l);
    };
  }, [place]);

  /** The pointer, in the well's coordinates. */
  const pointerX = (e: PointerEvent<HTMLDivElement>) => {
    const r = e.currentTarget;
    return e.clientX - r.getBoundingClientRect().left - r.clientLeft + r.scrollLeft;
  };

  /* Lean the cap toward the pointer: a few px, more toward a pressed option. */
  const lean = (e: PointerEvent<HTMLDivElement>, reach: number) => {
    const l = light.current;
    if (!l || !liquid.current || reduced.current) return;
    const d = pointerX(e) - liquid.current.centre;
    gsap.to(l, { ...timing("follow"), overwrite: "auto", x: Math.max(-reach, Math.min(reach, d * 0.08)) });
  };
  const unlean = () => {
    const l = light.current;
    if (l && !reduced.current) gsap.to(l, { ...timing("rebound"), overwrite: "auto", x: 0 });
  };

  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    const cap = liquid.current;
    if (e.button !== 0 || disabled || !cap) return;
    const option = (e.target as Element).closest('[role="radio"]');
    if (!option || option.hasAttribute("data-disabled")) return;
    pressing.current = true;
    lift();
    if (reduced.current) return;
    if (option.getAttribute("aria-checked") !== "true") {
      lean(e, 10);
      return;
    }
    const x = pointerX(e);
    grab.current = { offset: x - cap.centre, startX: x, moved: false };
    e.currentTarget.setPointerCapture(e.pointerId);
  };

  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    const g = grab.current;
    if (!g && e.pointerType === "mouse") lean(e, pressing.current ? 10 : 5);
    const cap = liquid.current;
    if (!g || !cap) return;
    const x = pointerX(e);
    if (Math.abs(x - g.startX) > 4) g.moved = true;
    if (!g.moved) return;
    const all = segments().filter((s) => !s.disabled);
    if (!all.length) return;
    const min = all[0]!.centre;
    const max = all.at(-1)!.centre;
    let to = x - g.offset;
    if (to < min) to = min + rubberband(to - min, 24);
    if (to > max) to = max + rubberband(to - max, 24);
    // Glued to the finger, taking the width of whatever it is over.
    const under = all.reduce((a, b) => (Math.abs(b.centre - to) < Math.abs(a.centre - to) ? b : a));
    cap.follow(to, under.width);
  };

  const onPointerUp = (e: PointerEvent<HTMLDivElement>) => {
    pressing.current = false;
    unlean();
    const g = grab.current;
    grab.current = null;
    const cap = liquid.current;
    if (!g) {
      // A press on another option: its click is about to send the cap over,
      // so it stays lifted; otherwise it settles.
      requestAnimationFrame(() => lift("rebound"));
      return;
    }
    if (e.currentTarget.hasPointerCapture(e.pointerId)) e.currentTarget.releasePointerCapture(e.pointerId);
    if (!g.moved || !cap) {
      lift("rebound");
      return;
    }
    // Where the throw was heading, not just where it was let go.
    const velocity = cap.velocity;
    const heading = cap.centre + velocity * 0.12;
    const all = segments().filter((s) => !s.disabled);
    if (!all.length) return;
    const landing = all.reduce((a, b) => (Math.abs(b.centre - heading) < Math.abs(a.centre - heading) ? b : a));
    cap.place({ start: landing.left, size: landing.width }, springs.bouncy, velocity);
    if (landing.index !== selected) {
      landing.el.focus();
      choose(landing.index);
    }
  };

  const choose = (i: number) => {
    if (i === selected) return;
    sound?.play("select");
    if (!isControlled) setInternal(i);
    onValueChange?.(i);
  };

  // Base UI's radio group doesn't handle Home and End; the segmented control
  // always did, so they jump to the first and last segment that's enabled.
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    // The caller's handler runs first and may take the key for itself.
    onKeyDownProp?.(e);
    if (e.defaultPrevented) return;
    if (e.key !== "Home" && e.key !== "End") return;
    const radios = [...e.currentTarget.querySelectorAll<HTMLElement>('[role="radio"]:not([data-disabled])')];
    const target = e.key === "Home" ? radios[0] : radios.at(-1);
    if (!target) return;
    e.preventDefault();
    target.focus();
    choose(Number(target.dataset.index));
  };

  return (
    <BaseRadioGroup
      ref={setRoot}
      className="echo-segmented"
      data-size={size}
      value={selected}
      disabled={disabled}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      onValueChange={(next) => choose(next as number)}
      onKeyDown={onKeyDown}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      onPointerEnter={(e) => {
        if (e.pointerType !== "mouse" || disabled) return;
        hovered.current = true;
        lift();
      }}
      onPointerLeave={() => {
        hovered.current = false;
        pressing.current = false;
        unlean();
        lift("rebound");
      }}
      {...interop}
    >
      <span ref={light} className="echo-segmented__light" aria-hidden>
        <span ref={shape} className="echo-segmented__shape" />
      </span>
      {options.map((option, i) => {
        const label = typeof option === "string" ? option : option.label;
        const content = typeof option === "string" ? undefined : option.content;
        return (
          <BaseRadio.Root
            // Keyed by position, not by label: a segment's identity here *is*
            // its index — that's what `value` and `data-index` are — and two
            // options may share a label. Keyed by label, React had two children
            // with the same key, reused one node for another's place and left
            // the third in the DOM, whose stale data-index is what Home and End
            // then read.
            key={i}
            value={i}
            disabled={typeof option === "string" ? undefined : option.disabled}
            className="echo-segmented__option"
            data-index={i}
            data-content={content !== undefined ? "" : undefined}
            aria-label={content !== undefined ? label : undefined}
          >
            {content ?? label}
          </BaseRadio.Root>
        );
      })}
    </BaseRadioGroup>
  );
});
